INSERT INTO public.source (id, title, source_type, author, edition, url, note)
SELECT id, title, source_type, author, edition, url, note FROM jsonb_populate_recordset(NULL::public.source, '[{"title": "宋史·卷481·世家四·南汉刘氏·潘崇彻附传", "source_type": "primary", "author": "脱脱等", "edition": "选定TXT逐字导出；电子本，纸本及异文待核。", "url": "https://github.com/greed-216/histree/blob/05c8382e0d397e9dac6d60dfa83048d6aa2e8137/content/books/zizhi-tongjian/vol-290/year-0951/part-11/sources/library/songshi-481-pan-chongche/source.txt", "note": "《宋史》卷481·世家四·南汉刘氏·潘崇彻附传，段落 songshi-9c6e46fee832-p075135；已核上下文及传主，纸本及异文待核。", "id": "1a83cb0c-b73c-56d8-8f59-6b6a9220ff37"}, {"title": "资治通鉴·卷290·广顺元年末至二年初·授任征赋与年界", "source_type": "primary", "author": "司马光等", "edition": "选定TXT逐字导出；电子本，纸本及异文待核。", "url": "https://github.com/greed-216/histree/blob/05c8382e0d397e9dac6d60dfa83048d6aa2e8137/content/books/zizhi-tongjian/vol-290/year-0951/part-11/sources/library/tongjian-290-951-final-appointments/source.txt", "note": "《资治通鉴》卷290·广顺元年末至二年初·授任征赋与年界，段落 zizhi-tongjian-a63549944a71-p003449；已核上下文及传主，纸本及异文待核。", "id": "80c4a2f1-88c0-5f6d-a274-6602daf65fbb"}, {"title": "新五代史·卷62·南唐世家·保大十年湖南征敛", "source_type": "primary", "author": "欧阳修", "edition": "选定TXT逐字导出；电子本，纸本及异文待核。", "url": "https://github.com/greed-216/histree/blob/05c8382e0d397e9dac6d60dfa83048d6aa2e8137/content/books/zizhi-tongjian/vol-290/year-0951/part-11/sources/library/xinwudaishi-062-hunan-taxation/source.txt", "note": "《新五代史》卷62·南唐世家·保大十年湖南征敛，段落 xin-wudaishi-b08f244b9241-p003147；已核上下文及传主，纸本及异文待核。", "id": "6e63d276-e9c7-5dad-ac5b-30507ffc449a"}, {"title": "新五代史·卷65·南汉世家·乾和九年冬取郴州", "source_type": "primary", "author": "欧阳修", "edition": "选定TXT逐字导出；电子本，纸本及异文待核。", "url": "https://github.com/greed-216/histree/blob/05c8382e0d397e9dac6d60dfa83048d6aa2e8137/content/books/zizhi-tongjian/vol-290/year-0951/part-11/sources/library/xinwudaishi-065-chenzhou-campaign/source.txt", "note": "《新五代史》卷65·南汉世家·乾和九年冬取郴州，段落 xin-wudaishi-b08f244b9241-p003286；已核上下文及传主，纸本及异文待核。", "id": "7d8b70d7-76c9-531d-85a2-a9b1e58d3aa4"}, {"title": "资治通鉴·卷290·广顺元年·十一月至十二月及年末追述", "source_type": "primary", "author": "司马光等", "edition": "选定TXT逐字导出；电子本，纸本及异文待核。", "url": "https://github.com/greed-216/histree/blob/97a2c54a1eb33b08fa864fe14e9ca184db2402cc/content/books/zizhi-tongjian/vol-290/year-0951/part-10/sources/library/tongjian-290-951-year-end/source.txt", "note": "《资治通鉴》卷290·广顺元年·十一月至十二月及年末追述，段落 zizhi-tongjian-a63549944a71-p003448；已核上下文及传主，纸本及异文待核。", "id": "67e73719-49e5-5b82-aaed-c024f28176b0"}, {"title": "旧五代史·卷112·太祖本纪三·广顺元年十二月", "source_type": "primary", "author": "薛居正等", "edition": "选定TXT逐字导出；电子本，纸本及异文待核。", "url": "https://github.com/greed-216/histree/blob/97a2c54a1eb33b08fa864fe14e9ca184db2402cc/content/books/zizhi-tongjian/vol-290/year-0951/part-10/sources/library/jiuwudaishi-112-december-expedition/source.txt", "note": "《旧五代史》卷112·太祖本纪三·广顺元年十二月，段落 jiu-wudaishi-205deb4a7860-p002668；已核上下文及传主，纸本及异文待核。", "id": "dc4d556d-5461-5f7f-afde-3c4a49643247"}, {"title": "新五代史·卷62·南唐世家·保大九年入楚", "source_type": "primary", "author": "欧阳修", "edition": "选定TXT逐字导出；电子本，纸本及异文待核。", "url": "https://github.com/greed-216/histree/blob/b5396b868c179978bf5637eb7c5dc784ba41bd1d/content/books/zizhi-tongjian/vol-290/year-0951/part-09/sources/library/xinwudaishi-062-chu-conquest/source.txt", "note": "《新五代史》卷62·南唐世家·保大九年入楚，段落 xin-wudaishi-b08f244b9241-p003146；已核上下文及传主，纸本及异文待核。", "id": "6a9c9e70-dbf0-5722-b8e9-19cc77f6cb1f"}, {"title": "宋史·卷261·列传二十·陈思让传·虒亭战事", "source_type": "primary", "author": "脱脱等", "edition": "选定TXT逐字导出；电子本，纸本及异文待核。", "url": "https://github.com/greed-216/histree/blob/b5396b868c179978bf5637eb7c5dc784ba41bd1d/content/books/zizhi-tongjian/vol-290/year-0951/part-09/sources/library/songshi-261-siting-battle/source.txt", "note": "《宋史》卷261·列传二十·陈思让传·虒亭战事，段落 songshi-9c6e46fee832-p058037；已核上下文及传主，纸本及异文待核。", "id": "69dda249-99cc-5cf2-88dc-87fe594abb5d"}]'::jsonb)
ON CONFLICT (id) DO NOTHING;

INSERT INTO public.person (id, name, aliases, era, birth_year, death_year, description, biography, status)
SELECT id, name, aliases, era, birth_year, death_year, description, biography, status FROM jsonb_populate_recordset(NULL::public.person, '[{"name": "慕容彦超", "aliases": ["慕容彥超"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "后晋濮州刺史，原属吐谷浑，与刘知远同母。945年正月随皇甫遇侦察契丹军，在榆林店受围，与皇甫遇共同救回杜知敏，得到安审琦援军后返回相州。出生及死亡年本段未载。", "biography": null, "status": "draft", "id": "e0c11a24-a441-5d69-b8e3-b5bdc109357b"}, {"name": "郭威", "aliases": [], "era": "五代十国", "birth_year": null, "death_year": null, "description": "《资治通鉴》卷272同光元年条所见人物：郭威。", "biography": null, "status": "draft", "id": "3fe84db3-aa25-5be9-9dd3-8b46e28213af"}, {"name": "刘崇（刘知远弟）", "aliases": ["劉崇（劉知遠弟）", "刘旻", "劉旻"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "刘知远的弟弟，后来名刘旻。947年任太原尹、知府事。与朱温早年寄居的萧县刘崇分别建档，具体生卒年尚未录入。", "biography": null, "status": "draft", "id": "edf0bd63-ab6d-577e-8623-9f2d759b6d97"}, {"name": "王峻", "aliases": [], "era": "五代十国", "birth_year": null, "death_year": null, "description": "安阳人，刘知远的客将。947年奉三表赴契丹，报告贺入大梁、暂不离太原及贡路受阻。《旧五代史》称牙将王峻，记二月出使和携杖回太原。生卒年本段未核。", "biography": null, "status": "draft", "id": "196d9879-50e7-5ff5-9d99-4879fa1ea3a2"}, {"name": "仇弘超", "aliases": [], "era": "五代十国", "birth_year": null, "death_year": null, "description": "后周行营马军都指挥使。951年晋州解围后奉王峻之命，与药元福等率骑兵追击北汉军至霍邑。生卒年未载。", "biography": null, "status": "draft", "id": "bb1daa5f-b7e9-5259-8285-0a0145332b75"}, {"name": "药元福", "aliases": ["藥元福"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "并州晋阳人，早年侍奉王檀及后唐，曾任深州刺史。945年任后晋马军右厢副排阵使，在白团卫村被围时主张逆风急击，与符彦卿、张彦泽、皇甫遇领骑兵出战。《宋史》还记他战后任威州刺史。生卒年本次引文未载。", "biography": null, "status": "draft", "id": "9bbd6971-3005-5379-8428-512e90ae87d6"}, {"name": "陈思让", "aliases": ["陳思讓"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "后晋作坊使，幽州人。941年十一月受石重贵派遣讨伐安从进，丁丑获任先锋军监军。生卒年未据本段确定。", "biography": null, "status": "draft", "id": "59feec41-432b-5d18-829a-46def9523238"}, {"name": "康延沼", "aliases": ["康延昭"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "后周军官。951年奉王峻之命，与陈思让等率骑兵追击北汉军。《宋史》陈思让传同役记康延昭，与陈思让分任左右厢排阵使，按同场同职对应；未与康延泽合并。生卒年未载。", "biography": null, "status": "draft", "id": "6f34d961-5d5f-50b2-9435-9f018039f0a8"}, {"name": "萧禹厥", "aliases": ["蕭禹厥"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "契丹彰国节度使。951年奉命率奚、契丹五万军队与北汉会合进攻后周。其他同音姓名对应及生卒年待核。", "biography": null, "status": "draft", "id": "e1c51dfb-2b2f-536a-add4-53d5aeb00144"}, {"name": "李璟", "aliases": ["徐景通", "景通", "李景"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "《资治通鉴》卷272同光元年条所见人物：李璟。", "biography": null, "status": "draft", "id": "6bf72971-88c3-5187-8f25-98cde2a9554a"}, {"name": "宋齐丘", "aliases": [], "era": "五代十国", "birth_year": null, "death_year": null, "description": "《资治通鉴》卷268乾化二年条所见人物：宋齐丘。", "biography": null, "status": "draft", "id": "313ec6c3-7027-5fef-8b5d-b79d259f9c8a"}, {"name": "马希萼", "aliases": ["馬希萼"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "马希范的弟弟、马希广的兄长。947年马希范死时，任武平节度使、知永州事，部分将领主张拥立他，但最终马希广继位。生卒年尚未录入。", "biography": null, "status": "draft", "id": "9d5be246-b5ae-553e-b5c5-a6a875b2c1cd"}, {"name": "马希崇", "aliases": ["馬希崇"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "马希广的庶弟、马希萼的弟弟。947年任楚天策左司马，秘密致信马希萼指责继位安排，又向他报告马希广的言行并约为内应。生卒年尚未录入。", "biography": null, "status": "draft", "id": "7c876e99-eb52-5864-9569-0ede35f9ff7b"}, {"name": "廖偃", "aliases": [], "era": "五代十国", "birth_year": null, "death_year": null, "description": "廖匡图之子，楚国衡山指挥使。951年与叔父廖匡凝商议扶助被废的马希萼，率庄户和乡人，与彭师暠共同拥立马希萼为衡山王。生卒年未载。", "biography": null, "status": "draft", "id": "d604ed00-6b4d-52ea-bc7d-00a0c995ff48"}, {"name": "彭师暠", "aliases": ["彭師暠"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "彭士愁的儿子。940年受父亲派遣，率诸酋长向楚交出溪、锦、奖三州官印，请求归降。生卒年未载。", "biography": null, "status": "draft", "id": "9a01204b-6429-53ed-8ca1-76b3143bd4d8"}, {"name": "王赟（楚永州刺史）", "aliases": [], "era": "五代十国", "birth_year": null, "death_year": 951, "description": "楚国永州刺史。951年南唐要求湖南刺史入朝，他较晚到达，被李璟毒杀。与已录岳州刺史王赟是否同人仍待补证，暂不合并。此前履历和出生年未载。", "biography": null, "status": "draft", "id": "4b193f71-55fe-5de1-8ba3-34f7b1504885"}, {"name": "刘弘熙", "aliases": ["劉弘熙", "刘洪熙", "劉洪熙"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "本批《资治通鉴》与二十四史所见人物：刘弘熙，获封王爵之子。", "biography": null, "status": "draft", "id": "b67079e8-6ec8-5150-9451-5b3ce7983fec"}, {"name": "潘崇彻", "aliases": ["潘崇徹"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "南汉内侍省丞。951年与谢贯率兵攻郴州，在义章击败南唐援军。《宋史》附传记为广州南海人，官称写内侍省局丞。生卒年尚未录入。", "biography": null, "status": "draft", "id": "782ac0d2-821f-5328-ba70-7c1c10b7902b"}, {"name": "谢贯", "aliases": ["謝貫"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "南汉将军。951年与潘崇彻受命率兵攻郴州。生卒年未载。", "biography": null, "status": "draft", "id": "d10c7eff-3fdb-5724-baab-6b81559fe489"}, {"name": "边镐", "aliases": ["邊鎬"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "金陵人，南唐通事舍人。943年十月任讨张遇贤军监军，用白昌裕为谋主，接连获胜；白昌裕建议开道绕到营后袭击，张遇贤随后逃走被捕。生卒年尚未核。", "biography": null, "status": "draft", "id": "8bcc0004-3382-5f6c-af6e-73ccf4cdd725"}, {"name": "张峦", "aliases": ["張巒"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "南唐黑云指挥使。951年十二月任知全州，防备南汉。《新五代史》保大十年另记他出兵争桂管失败，时序另保留。生卒年未载。", "biography": null, "status": "draft", "id": "660a73c2-c72e-5e9c-a384-6c53eff0c794"}, {"name": "王延政", "aliases": [], "era": "五代十国", "birth_year": null, "death_year": null, "description": "本批《资治通鉴》与二十四史所见人物：王延政，都教练使、赴建州抚慰者。", "biography": null, "status": "draft", "id": "83601670-f3dc-5559-b599-e39bda91eb6c"}, {"name": "咸师朗", "aliases": ["咸師朗"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "蒙城镇将。949年南唐派皇甫晖到海州、泗州招纳淮北势力时，向皇甫晖投降。生卒年与其他经历未载。", "biography": null, "status": "draft", "id": "dc4e6f3f-cdad-5934-82a9-e901cc6f65dc"}, {"name": "杨继勋", "aliases": ["楊繼勳"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "南唐都官郎中。南唐取湖南以后被派去征收湖南租赋，以供驻军；史书记载征收苛刻、湖南人失望。生卒年未载。", "biography": null, "status": "draft", "id": "90b31171-9c7c-5c86-a4a0-b2cd4f4c15e9"}, {"name": "王绍颜", "aliases": ["王紹顏"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "南唐内侍。941年向李昪上书，指出春季以来许多群臣获罪，朝廷内外疑惧。李昪亲笔解释缘由，命王绍颜告知内外。生卒年未载。", "biography": null, "status": "draft", "id": "7b5d4362-d9f5-5b07-897d-a785905d4914"}, {"name": "孙朗", "aliases": ["孫朗"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "原随蒙城镇将咸师朗投降南唐的军人，后任奉节指挥使。南唐取湖南后因功赏和粮赐问题不满，与曹进商议杀王绍颜、边镐，夺取湖南归附中原。实际起事在952年另段，不提前录为951年既成事实。生卒年未载。", "biography": null, "status": "draft", "id": "becfbb42-fad5-53c5-ab22-fbcbaad91d0d"}, {"name": "曹进", "aliases": ["曹進"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "南唐奉节指挥使，原随咸师朗降唐。因功赏、粮赐问题，与孙朗商议杀王绍颜和边镐、夺湖南归附中原。此处为计划，实际起事另见952年。生卒年未载。", "biography": null, "status": "draft", "id": "8b8bc9ad-b3fa-5fbf-9fe9-2287b2a8811d"}]'::jsonb)
ON CONFLICT (id) DO NOTHING;

INSERT INTO public.event (id, title, start_year, end_year, time_original, dynasty, description, phases, location_name, location_modern_name, location_lat, location_lng, location_precision, location_note, status)
